/* Deferred when the HDMI playback endpoint is unavailable. No null sink substitute. */
#include "fixtures/native/media_test_host.h"
static void test_media_audio_mf_and_fallback_output(void){
 open_fixture(L"pcm.wav");CHECK("WAV is audio-only through MF",wait_ready()&&state().backend==1&&state().has_audio&&!state().has_video&&!state().audio_unavailable);CHECK("MF audio keeps low integrity",low_token());mediaview_control(MEDIA_PLAY,0);pump_media(600);CHECK("MF audio playback advances",state().position>.25);mediaview_control(MEDIA_PAUSE,0);pump_media(200);CHECK("MF audio pause acknowledged",state().paused);
 open_fixture(L"opus.opus");CHECK("Opus uses fallback audio path",wait_ready()&&state().backend==2&&state().has_audio&&!state().has_video&&!state().audio_unavailable);mediaview_control(MEDIA_PLAY,0);pump_media(600);CHECK("fallback audio advances",state().position>.25);mediaview_control(MEDIA_SEEK,3);mediaview_control(MEDIA_PAUSE,0);pump_media(350);CHECK("fallback audio seeks and pauses",state().paused&&fabs(state().position-3)<.2);mediaview_control(MEDIA_VOLUME,.4);pump_media(200);CHECK("audio volume acknowledged",fabs(state().volume-.4)<.001&&state().muted);
}
static void test_media_audio_video_streams_and_missing_output_reporting(void){open_fixture(L"h264_aac.mp4");CHECK("MF retains audio and video streams",wait_ready()&&state().has_video&&state().has_audio&&!state().audio_unavailable);open_fixture(L"vp9_opus.webm");CHECK("fallback retains audio and video streams",wait_ready()&&state().has_video&&state().has_audio&&!state().audio_unavailable);mediaview_clear();}
int wmain(int argc,wchar_t **argv){if(argc!=2)return 2;wcsncpy(fixtures,argv[1],32767);owner=CreateWindowExW(0,L"STATIC",L"Owned audio acceptance",WS_OVERLAPPEDWINDOW,0,0,800,600,NULL,NULL,GetModuleHandleW(NULL),NULL);if(!owner||mediaview_start(owner))return 2;mediaview_configure(25,1);test_media_audio_mf_and_fallback_output();test_media_audio_video_streams_and_missing_output_reporting();mediaview_stop();DestroyWindow(owner);printf("%d passed, %d failed; 2 audio selectors\n",passed,failed);return failed?1:0;}
